class Solution {
public:
    int maxFreq(string s, int maxLetters, int minSize, int maxSize) {
        unordered_map<string,int> cnt;
        int n = s.size(), ans = 0;
        for (int i = 0; i + minSize <= n; i++)
            for (int len = minSize; len <= maxSize && i + len <= n; len++) {
                string sub = s.substr(i, len);
                int mask = 0, d = 0;
                for (char c : sub) { if (!((mask >> (c-'a')) & 1)) { mask |= 1 << (c-'a'); d++; } }
                if (d <= maxLetters) ans = max(ans, ++cnt[sub]);
            }
        return ans;
    }
};

