class Solution:
    def maxFreq(self, s: str, maxLetters: int, minSize: int, maxSize: int) -> int:
        freq = [0] * 26
        distinct = 0
        cnt = {}
        ans = 0
        for i, ch in enumerate(s):
            j = ord(ch) - 97
            if freq[j] == 0:
                distinct += 1
            freq[j] += 1
            if i >= minSize:
                k = ord(s[i - minSize]) - 97
                freq[k] -= 1
                if freq[k] == 0:
                    distinct -= 1
            if i >= minSize - 1 and distinct <= maxLetters:
                sub = s[i - minSize + 1:i + 1]
                cnt[sub] = cnt.get(sub, 0) + 1
                if cnt[sub] > ans:
                    ans = cnt[sub]
        return ans

