class Solution {
public:
    int maxFreq(string s, int maxLetters, int minSize, int maxSize) {
        int freq[26] = {0}, distinct = 0, ans = 0;
        unordered_map<string,int> cnt;
        for (int i = 0; i < (int)s.size(); i++) {
            if (freq[s[i]-'a']++ == 0) distinct++;
            if (i >= minSize && --freq[s[i-minSize]-'a'] == 0) distinct--;
            if (i >= minSize - 1 && distinct <= maxLetters)
                ans = max(ans, ++cnt[s.substr(i - minSize + 1, minSize)]);
        }
        return ans;
    }
};

