        int[] freq = new int[26];
        int distinct = 0, ans = 0;
        Map<String,Integer> cnt = new HashMap<>();
        for (int i = 0; i < s.length(); i++) {
            if (freq[s.charAt(i)-'a']++ == 0) distinct++;
            if (i >= minSize && --freq[s.charAt(i-minSize)-'a'] == 0) distinct--;
            if (i >= minSize - 1 && distinct <= maxLetters) {
                String sub = s.substring(i - minSize + 1, i + 1);
                int v = cnt.merge(sub, 1, Integer::sum);
                ans = Math.max(ans, v);
            }
        }
        return ans;
    }
}

