        if (i >= minSize - 1 && distinct <= maxLetters) {
            const sub = s.substring(i - minSize + 1, i + 1);
            const v = (cnt.get(sub) || 0) + 1;
            cnt.set(sub, v);
            ans = Math.max(ans, v);
        }
    }
    return ans;
};
